from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re

class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip = 0
        self.text = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.skip += 1
        elif tag in ('p', 'li', 'h1', 'h2', 'h3', 'tr', 'br'):
            self.text.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.skip:
            self.skip -= 1
        elif tag in ('p', 'li', 'h1', 'h2', 'h3', 'tr'):
            self.text.append('\n')
    def handle_data(self, text):
        if not self.skip:
            self.text.append(text)

root = Path('products/services/sqlite-lemon-squeezy')
terms = {'activate-your-store': r'identity|review|approval|test mode|live mode', 'getting-paid': r'payout|minimum|threshold', 'fees': r'fee|international|paypal', 'supported-countries': r'\bCanada\b', 'prohibited-products': r'artificial intelligence|\bAI\b|intellectual property|digital|license'}
records = {}
for slug, pattern in terms.items():
    path = root / 'raw' / (slug + '.html')
    data = path.read_bytes()
    page = Page()
    page.feed(data.decode('utf-8', errors='replace'))
    lines = dict.fromkeys(' '.join(line.split()) for line in ''.join(page.text).splitlines())
    matches = [line for line in lines if len(line) <= 1500 and re.search(pattern, line, re.I)]
    records[slug] = {'source': 'https://docs.lemonsqueezy.com/help/getting-started/' + slug, 'capture_sha256': hashlib.sha256(data).hexdigest(), 'matching_lines': len(matches), 'excerpts': matches[:25]}
output = root / 'seller-document-navigation.json'
output.write_text(json.dumps({'scope': 'Navigation to captured first-party wording. Verify excerpts in context before drawing conclusions.', 'documents': records}, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({slug: record['matching_lines'] for slug, record in records.items()}))
